  (1084, '알고리즘 편향과 공정성', $j$[{"title": "채용 모델의", "description": "채용 모델의 집단별 탈락률을 비교.", "topic": "알고리즘 편향과 공정성"}, {"title": "추천 결과에서", "description": "추천 결과에서 소수 집단 노출을 점검.", "topic": "알고리즘 편향과 공정성"}, {"title": "학습 표본의", "description": "학습 표본의 누락 집단을 조사.", "topic": "알고리즘 편향과 공정성"}]$j$),
  (1085, '보안과 전문가 책임', $j$[{"title": "고객 정보", "description": "고객 정보 노출 발견 시 보고 절차를 가동.", "topic": "보안과 전문가 책임"}, {"title": "배포 전", "description": "배포 전 위험을 책임자에게 문서로 전달.", "topic": "보안과 전문가 책임"}, {"title": "장애 공지에", "description": "장애 공지에 확인된 사실과 추정치를 구분.", "topic": "보안과 전문가 책임"}]$j$),
  (1086, '지식재산과 오픈소스 윤리', $j$[{"title": "외부 코드의", "description": "외부 코드의 라이선스 고지를 배포물에 포함.", "topic": "지식재산과 오픈소스 윤리"}, {"title": "협업 문서의", "description": "협업 문서의 저자 기여를 표시.", "topic": "지식재산과 오픈소스 윤리"}, {"title": "공개 저장소에", "description": "공개 저장소에 올릴 자료의 사용 권한을 검토.", "topic": "지식재산과 오픈소스 윤리"}]$j$),
  (1087, '접근성과 디지털 격차', $j$[{"title": "공공 웹페이지의", "description": "공공 웹페이지의 키보드 이동 순서를 점검.", "topic": "접근성과 디지털 격차"}, {"title": "저속 통신", "description": "저속 통신 환경에서도 신청서를 작성하게 설계.", "topic": "접근성과 디지털 격차"}, {"title": "무인 접수기에", "description": "무인 접수기에 음성 안내를 제공.", "topic": "접근성과 디지털 격차"}]$j$),
  (1088, 'AI 책임성과 사회적 영향', $j$[{"title": "자동 심사", "description": "자동 심사 결과에 이의 신청 통로를 마련.", "topic": "AI 책임성과 사회적 영향"}, {"title": "생성형 AI", "description": "생성형 AI 안내문을 공개 전에 사실 검토.", "topic": "AI 책임성과 사회적 영향"}, {"title": "모델 도입", "description": "모델 도입 영향 평가에 당사자 의견을 반영.", "topic": "AI 책임성과 사회적 영향"}]$j$)
) as v(id, name, examples)
join public.c2c_course_concepts k on k.id = v.id and k.name = v.name
where exists (select 1 from public.c2c_curriculum_courses cc where cc.course_id = k.course_id
  and coalesce(cc.requirement_label, cc.course_category) in ('교양','교직','일반선택','기본소양'))
on conflict (cache_key) do update set examples = excluded.examples, model = excluded.model
where c2c_concept_examples.examples is distinct from excluded.examples or c2c_concept_examples.model is distinct from excluded.model;
